import assert from 'node:assert/strict';

export function schemaSnapshot(query, schema) {
  // Schema identifiers are generated by the verification scripts, never accepted from input.
  const db = `'${schema}'`;
  const rows = sql => query(sql).trim().split(/\r?\n/).filter(Boolean)
    .map(line => line.split('\t').join(' | '));
  return {
    tables: rows(`SELECT table_name,engine,table_collation FROM information_schema.tables WHERE table_schema=${db} AND table_name<>'flyway_schema_history' ORDER BY 1;`),
    columns: rows(`SELECT table_name,column_name,ordinal_position,column_type,is_nullable,IFNULL(column_default,'<NULL>'),IFNULL(character_set_name,''),IFNULL(collation_name,''),column_key,extra,IFNULL(generation_expression,'') FROM information_schema.columns WHERE table_schema=${db} AND table_name<>'flyway_schema_history' ORDER BY 1,3;`),
    indexes: rows(`SELECT table_name,index_name,non_unique,seq_in_index,IFNULL(column_name,''),IFNULL(sub_part,''),IFNULL(expression,'') FROM information_schema.statistics WHERE table_schema=${db} AND table_name<>'flyway_schema_history' ORDER BY 1,2,4;`),
    foreignKeys: rows(`SELECT rc.table_name,rc.constraint_name,rc.referenced_table_name,rc.update_rule,rc.delete_rule,GROUP_CONCAT(CONCAT(k.column_name,'->',k.referenced_column_name) ORDER BY k.ordinal_position) FROM information_schema.referential_constraints rc JOIN information_schema.key_column_usage k ON k.constraint_schema=rc.constraint_schema AND k.constraint_name=rc.constraint_name AND k.table_name=rc.table_name WHERE rc.constraint_schema=${db} GROUP BY 1,2,3,4,5 ORDER BY 1,2;`),
    checks: rows(`SELECT tc.table_name,cc.constraint_name,cc.check_clause FROM information_schema.check_constraints cc JOIN information_schema.table_constraints tc ON tc.constraint_schema=cc.constraint_schema AND tc.constraint_name=cc.constraint_name WHERE cc.constraint_schema=${db} AND tc.table_name<>'flyway_schema_history' ORDER BY 1,2;`),
  };
}

export function compareSchemaSnapshots(flyway, standalone) {
  const counts = {};
  for (const kind of Object.keys(flyway)) {
    const a = new Set(flyway[kind]);
    const b = new Set(standalone[kind]);
    counts[kind] = a.size;
    const onlyFlyway = [...a].filter(row => !b.has(row));
    const onlySchema = [...b].filter(row => !a.has(row));
    assert.deepEqual({ onlyFlyway, onlySchema }, { onlyFlyway: [], onlySchema: [] },
      `Flyway와 schema-mysql.sql 불일치: ${kind}`);
  }
  assert.ok(counts.tables >= 15 && counts.columns >= 125, '스키마 비교 범위 축소');
  return counts;
}
